import React from "react";
function Point(){
    return(
<div className="flex flex-col items-start pt-[35px] pb-[-20px] mb-[89px] ml-[118px] mr-24 gap-16 rounded-[22px]" 
	style={{
		background: "linear-gradient(180deg, #0066B2, #002B4C)"
	}}>
	<span className="text-white text-5xl font-bold ml-[395px]" >
		{"POINTS TO PONDER"}
	</span>
	<div className="flex items-start ml-[84px]">
		<div className="flex flex-col shrink-0 items-start pb-[141px] mt-8 mr-20 gap-[42px]">
			<div className="flex flex-col items-start bg-[#F7F7F7] pl-[30px] pr-[30px] rounded-[20px]" 
				style={{
					boxShadow: "5px 3px 10px #0000008C"
				}}>
				<span className="text-[#2E3192] text-3xl font-bold w-[690px]" >
					{"A scalable and customizable teaching aid to support English learning, even in remote corners of the country."}
				</span>
			</div>
			<div className="flex flex-col items-start bg-[#F7F7F7] pt-3 pb-[23px] pl-8 pr-[3px] rounded-[10px]" 
				style={{
					boxShadow: "5px 3px 10px #0000008C"
				}}>
				<span className="text-[#2E3192] text-3xl font-bold w-[719px]" >
					{"Integration of technology and AI in current learning and adaptability for future readiness."}
				</span>
			</div>
			<div className="flex flex-col items-start bg-[#F7F7F7] text-left py-1.5 px-[29px] rounded-[10px] border-0" 
				style={{
					boxShadow: "5px 3px 10px #0000008C"
				}}>-
				<span className="text-[#2E3192] text-3xl font-bold w-[739px]" >
					{"An economical and reliable solution for various gaps in English learning , proven with 100+ students."}
				</span>
			</div>
		</div>
		<img
			src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/iv0xhfvs_expires_30_days.png"} 
			className="w-[672px] h-[526px] rounded-[22px] object-fill"
		/>
	</div>
</div>

    );
}
export default Point;
